INSERT INTO settings (key, value, updated_at) VALUES ('service_pages', '{"web-design":{"service_id":"web-design","problem_text":"Most Zimbabwean businesses are invisible online. Your customers are searching for what you sell right now. If you do not have a professional website, they are finding your competitor instead.","what_heading":"What we build","what_intro":"We build websites that work. Not just visually — but technically, commercially and practically for the Zimbabwean market.","what_items":[{"title":"Business websites","body":"Professional, fast and credible. Built to represent your business and convert visitors into customers."},{"title":"E-commerce stores","body":"Sell online with local payment integration. EcoCash, InnBucks, Paynow and more — built in from day one."},{"title":"Landing pages","body":"Single-purpose pages designed to capture leads, promote a service or drive one specific action."},{"title":"School websites","body":"Built for Zimbabwean educational institutions. Timetables, notices, staff pages and parent communication."},{"title":"NGO & church sites","body":"Professional digital presence for organisations, ministries and charities across Zimbabwe."},{"title":"Website redesigns","body":"If your current site is outdated, slow or not converting, we rebuild it properly."},{"title":"Website maintenance","body":"Ongoing updates, security and performance so your site never falls behind."}],"price_range":"$30 – $1,000+","price_summary":"Packages from $30 up to custom enterprise scope.","price_note":"Hosting from $10/month. Every package includes mobile responsiveness, SSL security and local support.","process_steps":[{"title":"Brief","body":"You tell us what you need. We ask the right questions."},{"title":"Design","body":"We design your site and show you before we build anything."},{"title":"Build","body":"We build it exactly as approved. You stay updated throughout."},{"title":"Review","body":"You check everything. We fix anything that needs chan