UPDATE service_extras SET hero_eyebrow = 'Website Design & Development', hero_headline = 'A website that represents your business the way it deserves to be represented.', hero_intro = 'We design and develop professional websites for businesses, NGOs, schools, churches and organisations across Zimbabwe — built to be fast, credible and ready to grow with you.', hero_cta = 'View Packages', hero_background = '/images/hero-website-design.png', visual_background = '/images/service-web-design.png', hero_background_kind = 'image', hero_gradient = '160deg,#1a1a1a,#454545', updated_at = datetime('now') WHERE service_id = 'web-design';
