UPDATE service_extras SET hero_eyebrow = 'AI Solutions & Automation', hero_headline = 'Stop doing manually what technology can do for you.', hero_intro = 'We build practical AI tools and automated workflows that reduce repetitive work and help your organisation operate more efficiently — grounded in what your business actually needs, not technology for the sake of it.', hero_cta = 'Discuss Your Project', hero_background = '/images/hero-ai-automation.png', visual_background = '/images/service-ai.jpg', hero_background_kind = 'image', hero_gradient = '160deg,#1a1a1a,#454545', updated_at = datetime('now') WHERE service_id = 'ai-automation';
UPDATE service_extras SET hero_eyebrow = 'Graphic Design & Branding', hero_headline = 'Your brand is the first impression. Make it the right one.', hero_intro = 'We design logos, marketing materials and visual identities that make your business look credible, consistent and ready to compete — across digital and print platforms.', hero_cta = 'See Our Work', hero_background = '/images/hero-graphic-design.png', visual_background = '/images/service-graphic.png', hero_background_kind = 'image', hero_gradient = '160deg,#E85D2A,#F4A226', updated_at = datetime('now') WHERE service_id = 'graphic-design';
UPDATE service_extras SET hero_eyebrow = 'Domain Registration & Web Hosting', hero_headline = 'Your domain. Your brand. Your foundation — set up correctly from the start.', hero_intro = 'We register domains, set up reliable hosting and configure professional business email — the digital infrastructure every serious organisation needs, handled correctly from day one.', hero_cta = 'View Pricing', hero_background = '/images/hero-domains-hosting.png', visual_background = '/images/service-hosting.png', hero_background_kind = 'image', hero_gradient = '160deg,#454545,#6b7280', updated_at = datetime('now') WHERE service_id = 'domains-hosting';
UPDATE service_extras SET hero_eyebrow = 'API & System Integrations', hero_headline = 'Your systems should work together. We make sure they do.', hero_intro = 'We connect your website, software, payment platforms and third-party tools so your digital systems work as one joined-up environment instead of a collection of disconnected parts.', hero_cta = 'Discuss Your Project', hero_background = '/images/hero-api-integrations.png', visual_background = '/images/service-api.jpg', hero_background_kind = 'image', hero_gradient = '160deg,#1a1a1a,#6b7280', updated_at = datetime('now') WHERE service_id = 'api-integrations';
